class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        s = set(nums)
        best = 0
        for x in s:                     # 遍历集合，不是遍历 nums
            if x - 1 in s:
                continue                # 不是起点，跳过
            y = x
            while y + 1 in s:
                y += 1
            best = max(best, y - x + 1)
        return best

class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        lens, best = {}, 0
        for x in nums:
            if x not in lens:
                l, r = lens.get(x - 1, 0), lens.get(x + 1, 0)
                lens[x] = lens[x - l] = lens[x + r] = l + r + 1
                best = max(best, l + r + 1)
        return best

